{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "len(input_text) <= 10000",
      "description": "The length of the input text is no more than 10000 characters."
    },
    {
      "id": "P2",
      "expression": "input_text.isalpha() or input_text.isspace() or input_text in '.,!?'",
      "description": "The input text consists of lowercase Latin letters, spaces, and punctuation marks."
    },
    {
      "id": "P3",
      "expression": "input_text[0].isalpha() and input_text[-1].isalpha()",
      "description": "The text begins and ends with a Latin letter."
    },
    {
      "id": "P4",
      "expression": "all(input_text[i].isalpha() and input_text[i+1].isalpha() for i in range(len(input_text)-1) if input_text[i] == ' ' and input_text[i+1] == ' ')",
      "description": "There are no consecutive spaces in the input text."
    },
    {
      "id": "P5",
      "expression": "all(input_text[i].isalpha() and input_text[i+1] in '.,!?' for i in range(len(input_text)-1) if input_text[i] != ' ' and input_text[i+1] != ' ')",
      "description": "There is at least one word between any two punctuation marks."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "output_text.replace('  ', ' ').rstrip() == input_text.replace('  ', ' ').rstrip()",
      "description": "The output text has no extra spaces at the end and no consecutive spaces."
    },
    {
      "id": "Q2",
      "expression": "all(output_text[i] == ' ' and output_text[i+1] not in '.,!?' for i in range(len(output_text)-1) if output_text[i].isalpha() and output_text[i+1].isalpha())",
      "description": "Words are separated by exactly one space if there is no punctuation mark between them."
    },
    {
      "id": "Q3",
      "expression": "all(output_text[i] in '.,!?' and output_text[i+1] == ' ' for i in range(len(output_text)-1) if output_text[i].isalpha())",
      "description": "There is exactly one space after each punctuation mark."
    },
    {
      "id": "Q4",
      "expression": "all(output_text[i] not in '.,!?' or output_text[i-1] == ' ' for i in range(len(output_text)))",
      "description": "There are no spaces before each punctuation mark."
    }
  ],
  "invariants": []
}
